"""vic2orious: C64 hires/multicolour bitmaps with per-line multiplexed sprites."""

import os
import re

# recorded in the .v2i metadata ("generated by") and by tools/img2c64.py ("quantized by");
# web/js/version.js holds it, for the engine (web/js) that writes both
with open(os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
                       "web", "js", "version.js")) as _f:
    VERSION = re.search(r'VERSION = "([^"]+)"', _f.read()).group(1)
